css:
.vestedsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2b2f36;
    background: linear-gradient(160deg, #f4f1ea 0%, #ece7dc 60%, #e4ddcd 100%);
    border-radius: 16px;
}

.vestedsim-container * {
    box-sizing: border-box;
}

.vestedsim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #1f2933 0%, #2c3a47 55%, #394b5a 100%);
    color: #f6f2e9;
    border-radius: 14px;
    margin-bottom: 20px;
    border: 1px solid #19222b;
    box-shadow: 0 14px 36px rgba(31, 41, 51, 0.35);
}

.vestedsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #f8f4ec;
}

.vestedsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f0b75c;
    background: rgba(240, 183, 92, 0.14);
    border: 1px solid rgba(240, 183, 92, 0.40);
    padding: 5px 14px;
    border-radius: 4px;
}

.vestedsim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d6d0c4;
}

.vestedsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #5a6470;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.vestedsim-period-counter #currentDay,
.vestedsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #b9762a;
}

.vestedsim-round-name {
    background: #2c3a47;
    color: #f0b75c;
    padding: 3px 12px;
    border-radius: 4px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.vestedsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a3b2e;
    background: rgba(154, 59, 46, 0.10);
    border: 1px solid rgba(154, 59, 46, 0.30);
    padding: 4px 12px;
    border-radius: 4px;
}

.vestedsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.vestedsim-status-card {
    background: #ffffff;
    border-radius: 10px;
    padding: 16px 16px 14px;
    border: 1px solid #ddd6c8;
    box-shadow: 0 5px 16px rgba(57, 49, 33, 0.08);
    border-top: 4px solid #8a929b;
}

.vestedsim-card-savings { border-top-color: #2f8f5b; }
.vestedsim-card-align { border-top-color: #b9762a; }
.vestedsim-card-rel { border-top-color: #3a6ea5; }
.vestedsim-card-risk { border-top-color: #9a3b2e; }

.vestedsim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #7a8290;
}

.vestedsim-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1f2933;
    font-variant-numeric: tabular-nums;
}

.vestedsim-card-savings .vestedsim-value { color: #2f8f5b; }
.vestedsim-card-align .vestedsim-value { color: #b9762a; }
.vestedsim-card-rel .vestedsim-value { color: #3a6ea5; }
.vestedsim-card-risk .vestedsim-value { color: #9a3b2e; }

.vestedsim-sublabel {
    font-size: 0.76rem;
    color: #8a8275;
    line-height: 1.35;
}

.vestedsim-savings-short .vestedsim-value { color: #9a3b2e; }
.vestedsim-savings-met .vestedsim-value { color: #2f8f5b; }

.vestedsim-risk-high { border-top-color: #c0392b; }
.vestedsim-risk-high .vestedsim-value { color: #c0392b; }
.vestedsim-risk-low { border-top-color: #2f8f5b; }
.vestedsim-risk-low .vestedsim-value { color: #2f8f5b; }

.vestedsim-mandate-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #2c3a47;
    border: 1px solid #19222b;
    color: #e7e1d4;
    padding: 11px 18px;
    border-radius: 8px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.vestedsim-mandate-bar #mandateDisplay {
    font-size: 1.1rem;
    letter-spacing: 0.3px;
    color: #6fd49a;
}

.vestedsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #b9762a;
    border-radius: 8px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 5px 16px rgba(57, 49, 33, 0.08);
}

.vestedsim-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.vestedsim-briefing-title {
    font-weight: 800;
    font-size: 1.1rem;
    color: #1f2933;
    margin-bottom: 6px;
}

.vestedsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #4a4f57;
}

.vestedsim-briefing-text strong { color: #b9762a; }
.vestedsim-briefing-text em { color: #9a3b2e; font-style: italic; }

.vestedsim-controls {
    background: #ffffff;
    border-radius: 10px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #ddd6c8;
    box-shadow: 0 5px 16px rgba(57, 49, 33, 0.08);
}

.vestedsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1f2933;
    border-bottom: 2px solid #ece7dc;
    padding-bottom: 8px;
}

.vestedsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2b2f36;
    margin: 14px 0 6px;
}

.vestedsim-container select,
.vestedsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cbc2b0;
    border-radius: 7px;
    font-size: 0.92rem;
    background-color: #fbf9f4;
    color: #2b2f36;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.vestedsim-container select:focus,
.vestedsim-container input[type="number"]:focus {
    outline: none;
    border-color: #b9762a;
    box-shadow: 0 0 0 3px rgba(185, 118, 42, 0.18);
}

.vestedsim-container select option {
    background-color: #fbf9f4;
    color: #2b2f36;
}

.vestedsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #b9762a;
}

.vestedsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #5a6470;
    margin-top: 4px;
}

.vestedsim-range-readout span:nth-child(2),
.vestedsim-range-readout span#convictionReadout,
.vestedsim-range-readout span#squeezeReadout,
.vestedsim-range-readout span#gainshareReadout {
    color: #b9762a;
    font-weight: 800;
}

.vestedsim-hint {
    font-size: 0.8rem;
    color: #8a8275;
    margin-top: 6px;
    line-height: 1.45;
    background: #f6f3ec;
    border-left: 3px solid #d8cdb6;
    padding: 7px 10px;
    border-radius: 0 6px 6px 0;
}

.vestedsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.vestedsim-container .btn-primary {
    background: linear-gradient(135deg, #a8631f 0%, #d18b3a 100%);
    border: none;
    color: #fff7ea;
    padding: 11px 28px;
    border-radius: 7px;
    box-shadow: 0 8px 20px rgba(168, 99, 31, 0.32);
}

.vestedsim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.vestedsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cbc2b0;
    color: #5a6470;
    background: transparent;
}

.vestedsim-coach {
    background: linear-gradient(160deg, #1f2933 0%, #2c3a47 100%);
    color: #e3ddd0;
    border: 1px solid #19222b;
    border-radius: 10px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(31, 41, 51, 0.25);
}

.vestedsim-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f0b75c;
    margin-bottom: 8px;
}

.vestedsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.vestedsim-coach-body strong { color: #f0b75c; }
.vestedsim-coach-body em { color: #e89a8c; font-style: italic; }

.vestedsim-history,
.vestedsim-chart {
    background: #ffffff;
    border-radius: 10px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #ddd6c8;
    box-shadow: 0 5px 16px rgba(57, 49, 33, 0.08);
}

.vestedsim-history h3,
.vestedsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1f2933;
}

.vestedsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #4a4f57;
}

.vestedsim-container table#usfHistoryTable th {
    background: #2c3a47;
    color: #f0b75c;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #19222b;
}

.vestedsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #ece7dc;
    color: #4a4f57;
}

.vestedsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf8f2;
}

.vestedsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .vestedsim-container {
        padding: 14px;
    }
    .vestedsim-header h1 {
        font-size: 1.7rem;
    }
    .vestedsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .vestedsim-value {
        font-size: 2.05rem;
    }
    .vestedsim-clock {
        margin-left: 0;
    }
    .vestedsim-period-counter {
        font-size: 0.88rem;
    }
    .vestedsim-mandate-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .vestedsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* === vestedsim-cm: completion debrief (appended, adapter 1.1.0) === */
.vestedsim-cm { max-width: 640px; margin: 0 auto; font-family: inherit; }
.vestedsim-cm-head { display: flex; align-items: baseline; gap: 14px; flex-wrap: wrap; margin-bottom: 14px; }
.vestedsim-cm-score { font-size: 3rem; font-weight: 800; line-height: 1; color: #0b3d5c; }
.vestedsim-cm-max { font-size: 1.1rem; font-weight: 600; color: #6b7a86; margin-left: 2px; }
.vestedsim-cm-grade { font-size: 1.25rem; font-weight: 700; color: #123; }
.vestedsim-cm-badges { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 16px; }
.vestedsim-cm-badge { font-size: .82rem; font-weight: 600; padding: 4px 10px; border-radius: 999px; border: 1px solid transparent; }
.vestedsim-cm-ok { background: #e4f5ea; color: #1c7a43; border-color: #b7e2c7; }
.vestedsim-cm-no { background: #fdecec; color: #b23b3b; border-color: #f3c4c4; }
.vestedsim-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(96px, 1fr)); gap: 10px; margin-bottom: 16px; }
.vestedsim-cm-kpi { background: #f4f7f9; border: 1px solid #e1e8ed; border-radius: 8px; padding: 10px 8px; text-align: center; }
.vestedsim-cm-kpi-v { font-size: 1.2rem; font-weight: 700; color: #0b3d5c; }
.vestedsim-cm-kpi-l { font-size: .74rem; color: #6b7a86; margin-top: 3px; }
.vestedsim-cm-insights { margin: 0; padding-left: 20px; }
.vestedsim-cm-insights li { margin: 5px 0; line-height: 1.4; }

