(function() {
    'use strict';

    class VestedAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Vested or Bust`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Cumberland Health Brands / Apex Logistics).
            this.SPEND = 64;            // USD 64M/year Apex contract value
            this.MANDATE = 7.7;         // USD 7.7M run-rate savings mandate (12% of 64M)
            this.AUTOMATION = 4.8;      // USD 4.8M/yr of Apex revenue the automation would cut (~18% of picks)
            this.FAILURE_COST = 3.1;    // ~USD 3.1M/quarter chargebacks + expediting
            this.SWITCH_LOW = 6;        // USD 6M low end of re-bid switching cost
            this.SWITCH_HIGH = 9;       // USD 9M high end of re-bid switching cost

            // Concept truths (the target state).
            this.TRUE_CLASSIFY = `strategic`;
            this.TRUE_ROOT = `inverted`;
            this.TRUE_MODEL = `vested`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    savings: 0,      // USD M run-rate savings credited to the CFO mandate
                    align: 25,       // incentive alignment (does Apex earn more by saving you money?)
                    rel: 30,         // relationship + governance strength
                    risk: 60,        // dispute / service / BATNA / renewal risk (lower better)
                    squeezeReflex: false,
                    vestedInName: false,
                    noBaseline: false,
                    bluffedRebid: false,
                    savingsHistory: [0],
                    alignHistory: [25],
                    relHistory: [30],
                    riskHistory: [60],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately middling / wrong-leaning mix —
                // a blind click-through must not auto-win.
                state.decisions = {
                    classify: `transactional`,
                    root: `performance`,
                    conviction: 50,
                    model: `squeeze`,
                    scope: `activities`,
                    squeeze: 6,
                    gainshare: 20,
                    baseline: `estimate`,
                    governance: `penalty`,
                    apex: `mandate`,
                    cfo: `headline`,
                    batna: `bluff`,
                    resolve: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const cl = document.getElementById(`classifyInput`);
                const rt = document.getElementById(`rootInput`);
                const cv = document.getElementById(`convictionInput`);
                if (cl) decisions.classify = cl.value;
                if (rt) decisions.root = rt.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            } else if (round === 2) {
                const md = document.getElementById(`modelInput`);
                const sc = document.getElementById(`scopeInput`);
                const sq = document.getElementById(`squeezeInput`);
                if (md) decisions.model = md.value;
                if (sc) decisions.scope = sc.value;
                if (sq) decisions.squeeze = parseInt(sq.value, 10);
                if (!Number.isFinite(decisions.squeeze) || decisions.squeeze < 0 || decisions.squeeze > 20) {
                    warn(`warn_squeeze_range`); return false;
                }
            } else if (round === 3) {
                const gs = document.getElementById(`gainshareInput`);
                const bl = document.getElementById(`baselineInput`);
                const gv = document.getElementById(`governanceInput`);
                if (gs) decisions.gainshare = parseInt(gs.value, 10);
                if (bl) decisions.baseline = bl.value;
                if (gv) decisions.governance = gv.value;
                if (!Number.isFinite(decisions.gainshare) || decisions.gainshare < 0 || decisions.gainshare > 60) {
                    warn(`warn_gainshare_range`); return false;
                }
            } else if (round === 4) {
                const ap = document.getElementById(`apexInput`);
                const cf = document.getElementById(`cfoInput`);
                const bt = document.getElementById(`batnaInput`);
                const rs = document.getElementById(`resolveInput`);
                if (ap) decisions.apex = ap.value;
                if (cf) decisions.cfo = cf.value;
                if (bt) decisions.batna = bt.value;
                if (rs) decisions.resolve = parseInt(rs.value, 10);
                if (!Number.isFinite(decisions.resolve) || decisions.resolve < 0 || decisions.resolve > 100) {
                    warn(`warn_resolve_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let savingsDelta = 0, alignDelta = 0, relDelta = 0, riskDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: contract-design problem, not a performance problem (Common Error 1).
                switch (d.classify) {
                    case `strategic`: alignDelta += 8; relDelta += 10; riskDelta -= 8; coachKey = `coach_r1_strategic`; break;
                    case `transactional`: alignDelta -= 4; riskDelta += 6; coachKey = `coach_r1_transactional`; break;
                    case `rebid`: relDelta -= 6; riskDelta += 12; coachKey = `coach_r1_rebid`; break;
                }

                // Name the root cause — the inverted incentive is the structural driver.
                switch (d.root) {
                    case `inverted`: alignDelta += 10; relDelta += 4; riskDelta -= 6; if (d.classify === `strategic`) coachKey = `coach_r1_sharp`; break;
                    case `performance`: alignDelta -= 6; riskDelta += 8; coachKey = `coach_r1_performance`; break;
                    case `price`: alignDelta -= 4; riskDelta += 6; break;
                    case `people`: relDelta -= 4; riskDelta += 6; break;
                }

                if (d.conviction >= 60) { relDelta += 5; riskDelta -= 4; }
                else if (d.conviction <= 25) { relDelta -= 4; riskDelta += 5; coachKey = `coach_r1_lowconviction`; }

                summaryKey = (d.classify === `strategic` && d.root === `inverted`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Choose the contract model (Common Errors 1 & 3).
                const cut = d.squeeze / 100;                 // fraction of rate cut demanded

                if (d.model === `squeeze`) {
                    // Squeeze reflex: books a paper saving but starves automation and reignites adversarialism.
                    savingsDelta += cut * this.SPEND * 0.6;  // discounted: only ~60% sticks; activity unchanged
                    alignDelta -= 8; relDelta -= 10; riskDelta += 14;
                    ds.squeezeReflex = true;
                    coachKey = `coach_r2_squeeze`;
                } else if (d.model === `performance`) {
                    // Better, but still pays per activity — partial alignment only.
                    savingsDelta += cut * this.SPEND * 0.7 + 1.0;
                    alignDelta += 4; relDelta += 4; riskDelta -= 3;
                    coachKey = `coach_r2_performance`;
                } else { // vested
                    // Outcome-based: unlocks the stalled automation (~USD 4.8M of structural cost) over the term.
                    savingsDelta += this.AUTOMATION * 0.55 + cut * this.SPEND * 0.4;
                    alignDelta += 12; relDelta += 8; riskDelta -= 6;
                    coachKey = `coach_r2_vested`;
                }

                // Scope: outcomes ('what') unlock innovation; activities ('how') lock it out (Common Error 3).
                switch (d.scope) {
                    case `outcomes`: alignDelta += 8; relDelta += 6; savingsDelta += 1.2; riskDelta -= 4; break;
                    case `activities`: alignDelta -= 8; savingsDelta -= 1.0; riskDelta += 6; coachKey = (d.model === `vested`) ? `coach_r2_howtrap` : coachKey; break;
                    case `mixed`: alignDelta -= 2; break;
                }

                // An aggressive cut even inside a Vested/performance frame still corrodes the relationship.
                if (d.squeeze >= 12) { relDelta -= 6; riskDelta += 5; if (d.model !== `squeeze`) coachKey = `coach_r2_overcut`; }

                summaryKey = (d.model === `vested` && d.scope === `outcomes` && d.squeeze <= 10) ? `sum_r2_good` :
                             (d.model === `squeeze` ? `sum_r2_squeeze` : `sum_r2_weak`);
            } else if (round === 3) {
                // Shared-value & governance (Common Errors 2 & 4).
                const g = d.gainshare;                       // % of verified savings shared with Apex

                // Gainshare converts the inverted incentive. Sweet spot ~30–45% (textbook gainsharing).
                if (g <= 5) {
                    // Vested-in-name-only risk: economics untouched, Apex still loses by saving you money.
                    alignDelta -= 10; relDelta -= 6; riskDelta += 8; ds.vestedInName = true;
                    coachKey = `coach_r3_noshare`;
                } else if (g >= 15 && g <= 45) {
                    alignDelta += 14; relDelta += 8; riskDelta -= 6;
                    // Apex's share is netted out of CHB's gross saving but the unlocked automation more than pays for it.
                    savingsDelta += this.AUTOMATION * 0.30 - (g / 100) * this.AUTOMATION * 0.25;
                    coachKey = `coach_r3_aligned`;
                } else {
                    // Over-generous: gives away too much of the CFO's net saving.
                    alignDelta += 6; relDelta += 4; savingsDelta -= (g - 45) / 100 * this.SPEND * 0.10;
                    coachKey = `coach_r3_toogenerous`;
                }

                // Baseline & open-book: the spine of shared value (Common Error 4).
                switch (d.baseline) {
                    case `openbook`: alignDelta += 8; relDelta += 10; riskDelta -= 10; break;
                    case `estimate`: riskDelta += 6; coachKey = (g >= 15) ? `coach_r3_nobaseline` : coachKey; break;
                    case `none`: alignDelta -= 6; relDelta -= 6; riskDelta += 12; ds.noBaseline = true; coachKey = `coach_r3_nobaseline`; break;
                }

                // Governance for the unforeseen (incomplete-contracts logic).
                switch (d.governance) {
                    case `relational`: relDelta += 12; riskDelta -= 10; break;
                    case `penalty`: relDelta -= 8; riskDelta += 8; coachKey = (coachKey === `coach_default`) ? `coach_r3_penalty` : coachKey; break;
                    case `charter`: relDelta += 2; riskDelta += 3; break;
                }

                summaryKey = (g >= 15 && g <= 45 && d.baseline === `openbook` && d.governance === `relational`) ? `sum_r3_good` :
                             (ds.vestedInName || ds.noBaseline ? `sum_r3_hollow` : `sum_r3_weak`);
            } else if (round === 4) {
                // Negotiate & defend (Common Errors 2 & 5).
                switch (d.apex) {
                    case `winwin`: alignDelta += 12; relDelta += 8; riskDelta -= 8; coachKey = `coach_r4_winwin`; break;
                    case `mandate`: alignDelta -= 6; relDelta -= 8; riskDelta += 8; coachKey = `coach_r4_mandate`; break;
                    case `charter`: alignDelta -= 4; relDelta += 2; riskDelta += 4; ds.vestedInName = true; coachKey = `coach_r4_charter`; break;
                }

                switch (d.cfo) {
                    case `tco`: savingsDelta += 1.5; relDelta += 4; riskDelta -= 6; coachKey = (d.apex === `winwin`) ? `coach_r4_landed` : coachKey; break;
                    case `headline`: riskDelta += 8; coachKey = `coach_r4_headline`; break;
                    case `soft`: savingsDelta -= 1.0; riskDelta += 4; coachKey = `coach_r4_soft`; break;
                }

                // BATNA realism: re-bid is a real floor (USD 6–9M, 9–12 months), not a bluff.
                switch (d.batna) {
                    case `honest`: relDelta += 6; riskDelta -= 8; break;
                    case `bluff`: relDelta -= 10; riskDelta += 12; ds.bluffedRebid = true; coachKey = `coach_r4_bluff`; break;
                    case `ignore`: riskDelta += 4; break;
                }

                if (d.resolve >= 60) { alignDelta += 5; relDelta += 4; riskDelta -= 4; }
                else if (d.resolve <= 25) { relDelta -= 5; riskDelta += 5; }

                summaryKey = (d.apex === `winwin` && d.cfo === `tco` && d.batna === `honest`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply deltas. Savings accumulate (USD M); the other KPIs clamp 0–100.
            ds.savings = Math.round((ds.savings + savingsDelta) * 10) / 10;
            ds.align = Math.max(0, Math.min(100, Math.round(ds.align + alignDelta)));
            ds.rel = Math.max(0, Math.min(100, Math.round(ds.rel + relDelta)));
            ds.risk = Math.max(0, Math.min(100, Math.round(ds.risk + riskDelta)));

            ds.savingsHistory.push(ds.savings);
            ds.alignHistory.push(ds.align);
            ds.relHistory.push(ds.rel);
            ds.riskHistory.push(ds.risk);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 500);

            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            return {
                period: state.currentPeriod,
                savings: ds.savings,
                savingsDelta: Math.round(savingsDelta * 10) / 10,
                align: ds.align,
                alignDelta: Math.round(alignDelta),
                rel: ds.rel,
                relDelta: Math.round(relDelta),
                risk: ds.risk,
                riskDelta: Math.round(riskDelta),
                squeezeReflex: ds.squeezeReflex,
                vestedInName: ds.vestedInName,
                noBaseline: ds.noBaseline,
                bluffedRebid: ds.bluffedRebid,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
