        // _composite(ds): single source of truth for the 0-100 score (v1.0.0 formula, verbatim).
        _composite(ds) {
            const savings = ds.savings;
            const align = Math.round(ds.align);
            const rel = Math.round(ds.rel);
            const risk = Math.round(ds.risk);
            const savScore = Math.max(0, Math.min(25, (savings / this.MANDATE) * 25));
            return Math.round(align * 0.30 + rel * 0.28 + (100 - risk) * 0.26 + savScore * 0.64);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const savings = ds.savings;
            const align = Math.round(ds.align);
            const rel = Math.round(ds.rel);
            const risk = Math.round(ds.risk);

            // Composite via _composite(ds) — single source of truth (v1.0.0 formula).
            const composite = this._composite(ds);

            const hitMandate = savings >= this.MANDATE;
            const aligned = align >= 60;
            const durable = rel >= 60 && risk <= 35;
            const hollow = ds.vestedInName || ds.noBaseline;

            let performanceKey = `grade_broken`;
            if (hitMandate && aligned && durable && composite >= 75) performanceKey = `grade_vested`;
            else if (aligned && durable) performanceKey = `grade_transformed`;
            else if (ds.squeezeReflex && align < 45) performanceKey = `grade_squeeze`;
            else if (hollow) performanceKey = `grade_hollow`;
            else if (composite >= 55) performanceKey = `grade_mixed`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (hitMandate && aligned && durable) insights.push(window.mySimulation.t(`insight_vested`));
            else if (ds.squeezeReflex && align < 45) insights.push(window.mySimulation.t(`insight_squeeze`));
            else if (hollow) insights.push(window.mySimulation.t(`insight_hollow`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (!hitMandate) insights.push(window.mySimulation.t(`insight_savings_short`));
            else insights.push(window.mySimulation.t(`insight_savings_met`));
            if (ds.bluffedRebid) insights.push(window.mySimulation.t(`insight_bluff`));
            if (align >= 65 && risk <= 30) insights.push(window.mySimulation.t(`insight_aligned`));

            return {
                savings: savings,
                align: align,
                rel: rel,
                risk: risk,
                hitMandate: hitMandate,
                aligned: aligned,
                durable: durable,
                hollow: hollow,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: (hitMandate && aligned && durable),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const s = summary || {};
            const t = (k) => window.mySimulation.t(k);
            const esc = (x) => String(x == null ? `` : x).replace(/[&<>]/g, (c) => ({ '&': `&amp;`, '<': `&lt;`, '>': `&gt;` }[c]));
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || t(s.performanceKey || `grade_broken`);
            const badge = (ok, okKey, noKey) => `<span class="vestedsim-cm-badge ${ok ? `vestedsim-cm-ok` : `vestedsim-cm-no`}">${esc(t(ok ? okKey : noKey))}</span>`;
            const kpi = (label, val) => `<div class="vestedsim-cm-kpi"><div class="vestedsim-cm-kpi-v">${esc(val)}</div><div class="vestedsim-cm-kpi-l">${esc(label)}</div></div>`;
            const insights = (s.insights || []).map((i) => `<li>${esc(i)}</li>`).join(``);
            let badges = badge(s.hitMandate === true, `cm_badge_mandate`, `cm_badge_shortfall`)
                       + badge(s.aligned === true, `cm_badge_aligned`, `cm_badge_misaligned`)
                       + badge(s.durable === true, `cm_badge_durable`, `cm_badge_fragile`);
            if (s.hollow) badges += `<span class="vestedsim-cm-badge vestedsim-cm-no">${esc(t(`cm_badge_hollow`))}</span>`;
            const savings = (s.savings != null) ? this._fmtMoney(Number(s.savings)) : `\u2014`;
            return `<div class="vestedsim-cm">`
                + `<div class="vestedsim-cm-head"><div class="vestedsim-cm-score">${score}<span class="vestedsim-cm-max">/100</span></div>`
                + `<div class="vestedsim-cm-grade">${esc(grade)}</div></div>`
                + `<div class="vestedsim-cm-badges">${badges}</div>`
                + `<div class="vestedsim-cm-kpis">`
                + kpi(t(`cm_kpi_savings`), savings)
                + kpi(t(`cm_kpi_align`), (s.align != null ? s.align : `\u2014`))
                + kpi(t(`cm_kpi_rel`), (s.rel != null ? s.rel : `\u2014`))
                + kpi(t(`cm_kpi_risk`), (s.risk != null ? s.risk : `\u2014`))
                + kpi(t(`cm_kpi_index`), score)
                + `</div>`
                + (insights ? `<ul class="vestedsim-cm-insights">${insights}</ul>` : ``)
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.squeezeReflex && state.currentPeriod >= 2) return window.mySimulation.t(`hint_squeeze`);
            if (ds.vestedInName) return window.mySimulation.t(`hint_vestedinname`);
            if (ds.noBaseline) return window.mySimulation.t(`hint_baseline`);
            if (ds.risk >= 65) return window.mySimulation.t(`hint_risk`);
            if (state.currentPeriod >= 3 && ds.savings < this.MANDATE * 0.5) return window.mySimulation.t(`hint_savings`);
            if (ds.align >= 65 && ds.rel >= 60 && ds.risk <= 30) return window.mySimulation.t(`hint_strong`);
            return null;
        }

